begin;
create function pg_temp.forms_check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.forms_throws(code text,command text,label text)returns void language plpgsql as $$begin begin execute command;raise exception 'Expected SQLSTATE %',code;exception when others then if sqlstate<>code then raise exception 'FAIL %: expected %, actual % (%)',label,code,sqlstate,sqlerrm;end if;end;raise notice 'PASS: %',label;end$$;
select pg_temp.forms_check(not has_function_privilege('anon','public.save_form(uuid,uuid,text)','EXECUTE')and not has_function_privilege('service_role','public.save_form(uuid,uuid,text)','EXECUTE')and has_function_privilege('authenticated','public.save_form(uuid,uuid,text)','EXECUTE'),'public RPC explicitly revokes permissive default anon service and PUBLIC execution');
select pg_temp.forms_check(not has_function_privilege('authenticated','workforce_private.forms_eligible(uuid,uuid)','EXECUTE')and not has_function_privilege('authenticated','workforce_private.forms_lock_audience(uuid,jsonb)','EXECUTE'),'eligibility and write lock internals are not signed callable oracles');
select pg_temp.forms_check((select bool_and(not has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE'))from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','workforce_private')and c.relname in('forms','form_assignments','form_responses','form_audit','form_operations','form_response_history','form_history_counter')),'all seven application tables deny direct signed mutations');
select pg_temp.forms_check((select bool_and(not p.prosecdef and p.provolatile='s'and p.proconfig=array['search_path=""'])from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('read_forms','read_forms_access')),'read RPCs remain stable invoker with empty search path');
select pg_temp.forms_check((select bool_and(p.provolatile='v')from pg_proc p where p.proname='reconcile_form_operation'),'absence reconciliation uses fresh volatile snapshot after mutex waits');
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare t uuid:='88000000-0000-4000-8000-000000000001';c jsonb:='{"action":"create_form","name":"Boundary","description":"","schema":[],"audienceIds":[],"allowRespondentEdit":false}';s jsonb;before bigint;begin
 select count(*)into before from public.form_audit;
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||jsonb_build_object('name',repeat('😀',51)))::text),'direct RPC rejects 102 UTF16-unit name even with 51 codepoints');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||jsonb_build_object('name',chr(11)||chr(12)||chr(13)||chr(160)||chr(65279)))::text),'all JS whitespace-only names rejected directly');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||'{"unknown":null}')::text),'unknown nullable command property rejected directly');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||'{"allowRespondentEdit":null}')::text),'JSON null boolean rejected directly');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||'{"audienceIds":["{00000000-0000-4000-8000-000000000903}"]}')::text),'noncanonical PostgreSQL UUID audience spelling rejected');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||'{"audienceIds":["00000000-0000-4000-8000-000000000903","00000000-0000-4000-8000-000000000903"]}')::text),'duplicate static audience is rejected rather than truncated');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||'{"audienceIds":["00000000-0000-4000-8001-000000000001"]}')::text),'suspended audience member cannot enter new fixed audience');
 select jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'kind','text','label','Field','required',false))into s from generate_series(1,51);
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,(c||jsonb_build_object('schema',s))::text),'field cap rejects 51 without partial schema');
 perform pg_temp.forms_throws('22023',format('select public.save_form(%L,gen_random_uuid(),%L)',t,'{"action":"create_form","name":"Schema duplicate","description":"","schema":[{"id":"6f100000-0000-4000-8000-000000000001","kind":"text","label":"One","label":"Two","required":false}],"audienceIds":[],"allowRespondentEdit":false}'),'nested duplicate JSON label rejected before jsonb cast');
 perform pg_temp.forms_check((select count(*)from public.form_audit)=before,'invalid direct inputs preserve form audit and receipt write boundary');
end$$;
reset role;
do $$declare f uuid:=gen_random_uuid();s jsonb;v jsonb;begin
 s:=jsonb_build_array(jsonb_build_object('id',f,'kind','number','label','Number','required',false));
 perform pg_temp.forms_check(workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,''),false)and not workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,''),true)and workforce_private.forms_answers_valid(s,'{}',true),'partial empty numeric differs from omitted optional completed number');
 perform pg_temp.forms_check(workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,'-999999999999.999999'),true)and not workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,'1000000000000'),true)and not workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,'1e3'),true)and not workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,'NaN'),true),'complete numeric precision and exponent rejection preserve exact decimal strings');
 s:=jsonb_build_array(jsonb_build_object('id',f,'kind','text','label','Text','required',false));perform pg_temp.forms_check(workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,repeat('😀',2500)),true)and not workforce_private.forms_answers_valid(s,jsonb_build_object(f::text,repeat('😀',2501)),true),'UTF16 text boundary accepts 5000 units and rejects true overflow');
 s:=jsonb_build_array(jsonb_build_object('id',f,'kind','description','text',repeat(chr(1),5000)));perform pg_temp.forms_check(workforce_private.forms_schema_valid(s),'legal escaped control characters stay valid within semantic schema budget');
 select jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'kind','description','text',repeat(chr(1),5000)))into s from generate_series(1,5);perform pg_temp.forms_check(not workforce_private.forms_schema_valid(s),'semantic serialized schema budget counts escaped controls');
end$$;
-- Granted private readers must fail closed on SQL NULL authorization results.
insert into public.forms(id,tenant_id,name,description)values('6f300000-0000-4000-8000-000000000001','88000000-0000-4000-8000-000000000001','Private management metadata','');
insert into public.form_assignments(tenant_id,form_id,actor_id,name)values('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000903','Private assignment snapshot');
insert into auth.users(id,email_confirmed_at)values('6f300000-0000-4000-8000-000000000002',now());
set role authenticated;select set_config('request.jwt.claim.sub','6f300000-0000-4000-8000-000000000002',false);
select pg_temp.forms_check(workforce_private.forms_access('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','manage')is false,'foreign actor authorization helper returns false rather than NULL');
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_form_json('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','manage')$q$,'foreign actor cannot call granted management form helper');
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_assignees('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001')$q$,'foreign actor cannot call granted audience helper');
reset role;
update public.tenant_memberships set status='suspended'where tenant_id='88000000-0000-4000-8000-000000000001'and user_id='00000000-0000-4000-8000-000000000901';
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_form_json('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','manage')$q$,'suspended former owner cannot call granted form helper');
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_assignees('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001')$q$,'suspended former owner cannot call granted audience helper');
reset role;update public.tenant_memberships set status='active'where tenant_id='88000000-0000-4000-8000-000000000001'and user_id='00000000-0000-4000-8000-000000000901';update auth.users set email_confirmed_at=null where id='00000000-0000-4000-8000-000000000901';
set role authenticated;
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_form_json('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','manage')$q$,'unconfirmed owner cannot call granted form helper');
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_assignees('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001')$q$,'unconfirmed owner cannot call granted audience helper');
reset role;update auth.users set email_confirmed_at=now(),is_anonymous=true where id='00000000-0000-4000-8000-000000000901';
set role authenticated;
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_form_json('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','manage')$q$,'anonymous owner identity cannot call granted form helper');
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_assignees('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001')$q$,'anonymous owner identity cannot call granted audience helper');
reset role;update auth.users set is_anonymous=false where id='00000000-0000-4000-8000-000000000901';
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000903',false);
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_form_json('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001','manage')$q$,'active assigned manager cannot elevate to management helper');
select pg_temp.forms_throws('42501',$q$select workforce_private.forms_assignees('88000000-0000-4000-8000-000000000001','6f300000-0000-4000-8000-000000000001')$q$,'active assigned manager cannot read full management audience helper');
reset role;
-- More than 1000 users and form records: all pagination is exact, literal and nonduplicating.
insert into auth.users(id,email_confirmed_at)select ('6f200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now()from generate_series(1,505)n;
insert into public.tenant_memberships(tenant_id,user_id,display_name,role)select '88000000-0000-4000-8000-000000000001',id,'%_\ İ literal roster','employee'from auth.users where id::text like'6f200000-%';
update public.tenant_memberships set display_name='%_\ İ literal roster'where tenant_id='88000000-0000-4000-8000-000000000001'and user_id::text like'00000000-0000-4000-8001-%'and status='active';
insert into public.forms(id,tenant_id,name,description)select gen_random_uuid(),'88000000-0000-4000-8000-000000000001','%_\ İ literal catalog',''from generate_series(1,1005);
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare d jsonb;cur jsonb:=null;ids uuid[]:='{}';page integer:=0;u jsonb;t uuid:='88000000-0000-4000-8000-000000000001';begin
 loop d:=public.read_forms(t,'catalog','manage',null,null,'all','all','%_\ İ',100,cur);perform pg_temp.forms_check((d->'counts'->>'total')::integer=1005,'catalog exact searched total is not directory-truncated page '||page);for u in select value from jsonb_array_elements(d->'forms')loop ids:=array_append(ids,(u->>'id')::uuid);end loop;cur:=d->'nextCursor';page:=page+1;exit when cur='null'::jsonb;end loop;
 perform pg_temp.forms_check(cardinality(ids)=1005 and(select count(distinct id)from unnest(ids)id)=1005 and page=11,'literal catalog pages visit every one of 1005 distinct records once');
 ids:='{}';cur:=null;page:=0;
 loop d:=public.read_forms(t,'roster','manage',null,null,'all','all','%_\ İ',100,cur);if(d->>'matchedCount')::integer<>1005 then raise exception 'Roster exactcount %',d;end if;for u in select value from jsonb_array_elements(d->'users')loop ids:=array_append(ids,(u->>'actorId')::uuid);end loop;cur:=d->'nextCursor';page:=page+1;exit when cur='null'::jsonb;end loop;
 perform pg_temp.forms_check(cardinality(ids)=1005 and(select count(distinct id)from unnest(ids)id)=1005 and page=11,'searched roster retains SQL Turkish sort key and every eligible Auth record beyond 1000');
end$$;
rollback;
